from QuantConnect import Resolution
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Indicators import MovingAverageType
from QuantConnect.Orders import OrderStatus


class TwoSlotStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity(
            "SPY", Resolution.Daily, fill_forward=False
        ).Symbol
        self.aapl = self.AddEquity(
            "AAPL", Resolution.Daily, fill_forward=False
        ).Symbol
        self.ibm = self.AddEquity(
            "IBM", Resolution.Daily, fill_forward=False
        ).Symbol
        self.bac = self.AddEquity(
            "BAC", Resolution.Daily, fill_forward=False
        ).Symbol
        self.aig = self.AddEquity(
            "AIG", Resolution.Daily, fill_forward=False
        ).Symbol

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_pending_order = None
        self.strategy_b_pending_order = None

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data):
        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        aapl_bar = data.Bars[self.aapl] if self.aapl in data.Bars else None

        spy_close = None
        current_spy_sma = None
        previous_spy_close = self.previous_spy_close
        previous_spy_sma = self.previous_spy_sma

        if spy_bar is not None:
            spy_close = float(spy_bar.Close)

            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        if spy_close is not None and current_spy_sma is not None:
            self.previous_spy_close = spy_close
            self.previous_spy_sma = current_spy_sma

        if self.IsWarmingUp:
            return

        if any(symbol not in data.Bars for symbol in (
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        )):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_crosses_below = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and previous_spy_close <= previous_spy_sma
            and spy_close > current_spy_sma
        )

        spy_crosses_above = (
            previous_spy_close is not None
            and previous_spy_sma is not None
            and previous_spy_close >= previous_spy_sma
            and spy_close < current_spy_sma
        )

        aapl_rsi_above_60 = float(self.aapl_rsi.Current.Value) > 60

        # Evaluate sells before buys.
        if (
            self.strategy_a_lot > 0
            and self.strategy_a_pending_order is None
            and spy_crosses_above
        ):
            self._submit_sell(
                self.spy,
                self.strategy_a_lot,
                "Strategy A liquidation"
            )

        if (
            self.strategy_b_lot > 0
            and self.strategy_b_pending_order is None
            and aapl_rsi_above_60
        ):
            self._submit_sell(
                self.aapl,
                self.strategy_b_lot,
                "Strategy B liquidation"
            )

        # Strategy A buy.
        if (
            self.strategy_a_lot == 0
            and self.strategy_a_pending_order is None
            and spy_crosses_below
        ):
            portfolio_value = float(self.Portfolio.TotalPortfolioValue)
            quantity = int((0.40 * portfolio_value) / spy_close)

            if quantity > 0:
                self._submit_buy(
                    self.spy,
                    quantity,
                    "Strategy A buy"
                )

        # Strategy B buy.
        if (
            self.strategy_b_lot == 0
            and self.strategy_b_pending_order is None
            and self.aapl_red_streak >= 3
            and float(self.Portfolio.Cash) >= 20000
        ):
            quantity = int(20000 / aapl_bar.Close)

            if quantity > 0:
                self._submit_buy(
                    self.aapl,
                    quantity,
                    "Strategy B buy"
                )

    def _submit_buy(self, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag=tag)

        if ticket is None:
            return

        if symbol == self.spy:
            if ticket.Status not in self._terminal_statuses():
                self.strategy_a_pending_order = ticket.OrderId
        elif symbol == self.aapl:
            if ticket.Status not in self._terminal_statuses():
                self.strategy_b_pending_order = ticket.OrderId

    def _submit_sell(self, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, -quantity, tag=tag)

        if ticket is None:
            return

        if symbol == self.spy:
            if ticket.Status not in self._terminal_statuses():
                self.strategy_a_pending_order = ticket.OrderId
        elif symbol == self.aapl:
            if ticket.Status not in self._terminal_statuses():
                self.strategy_b_pending_order = ticket.OrderId

    def OnOrderEvent(self, order_event):
        fill_quantity = int(order_event.FillQuantity)

        if fill_quantity != 0:
            if order_event.Symbol == self.spy:
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + fill_quantity
                )
            elif order_event.Symbol == self.aapl:
                self.strategy_b_lot = max(
                    0,
                    self.strategy_b_lot + fill_quantity
                )

        if order_event.Status in self._terminal_statuses():
            if order_event.Symbol == self.spy:
                if self.strategy_a_pending_order == order_event.OrderId:
                    self.strategy_a_pending_order = None
            elif order_event.Symbol == self.aapl:
                if self.strategy_b_pending_order == order_event.OrderId:
                    self.strategy_b_pending_order = None

    @staticmethod
    def _terminal_statuses():
        return {
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        }
